# ---------------------------------------------------------------- sprites

class Sprite:
    """A picture (an image, or any emoji/text) that moves. Draws itself with ctx."""

    def __init__(self, picture, x=0, y=0, size=48):
        self.picture = picture
        self.x, self.y = x, y
        self.vx = self.vy = 0.0
        self.angle = 0.0
        self.size = size
        self.visible = True

    def update(self, dt):
        self.x += self.vx * dt
        self.y += self.vy * dt

    def draw(self):
        if not self.visible:
            return
        c = ctx
        c.save()
        c.translate(self.x, self.y)
        if self.angle:
            c.rotate(self.angle)
        s = self.size
        if isinstance(self.picture, str):
            # Emoji/text is drawn ONCE into a small canvas and stamped from then
            # on: redrawing text every frame is the slow path on phones.
            box = s * 1.3
            c.drawImage(_picture(self.picture, s), -box / 2, -box / 2, box, box)
        else:
            c.drawImage(self.picture, -s / 2, -s / 2, s, s)
        c.restore()

    def touches(self, other):
        r = (self.size + other.size) * 0.4
        return (self.x - other.x) ** 2 + (self.y - other.y) ** 2 < r * r


def _picture(text, size):
    key = (text, size)
    pic = S.pictures.get(key)
    if pic is None:
        ratio = (S.ns or {}).get("pixel_ratio", 1) or 1
        px = max(1, int(size * 1.3 * ratio + 0.5))
        pic = js.document.createElement("canvas")
        pic.width = px
        pic.height = px
        g = pic.getContext("2d")
        g.font = "%dpx system-ui, sans-serif" % int(size * ratio)
        g.textAlign = "center"
        g.textBaseline = "middle"
        g.fillText(text, px / 2, px / 2 + size * ratio * 0.06)
        S.pictures[key] = pic
    return pic


def load_image(src):
    """An image for drawImage or a Sprite. Draws once it has loaded."""
    img = js.Image()
    img.src = src
    return img


